INSERT INTO cities (city_id, city_name, province, region_type, description, source_url, date_retrieved) VALUES (1, 'Islamabad', 'Islamabad Capital Territory', 'Metropolitan', 'Purpose-built capital city designed by Constantinos Doxiadis in 1960. Known for high standard of living, lush greenery, Margalla Hills National Park, and modern architecture.', 'https://islamabad.gov.pk', TO_DATE('2024-11-20', 'YYYY-MM-DD'));
INSERT INTO cities (city_id, city_name, province, region_type, description, source_url, date_retrieved) VALUES (2, 'Lahore', 'Punjab', 'Historical', 'The cultural and historic heart of Pakistan with over a millennium of documented history. Renowned for UNESCO World Heritage Mughal architecture, vibrant street food culture, and literature.', 'https://tdcp.gop.pk', TO_DATE('2024-11-20', 'YYYY-MM-DD'));
INSERT INTO cities (city_id, city_name, province, region_type, description, source_url, date_retrieved) VALUES (3, 'Karachi', 'Sindh', 'Coastal', 'Pakistan''s largest metropolis, financial capital, and main seaport along the Arabian Sea coast. Famed for colonial architecture, beaches, diverse culinary scene, and maritime commerce.', 'https://stdc.gos.pk', TO_DATE('2024-11-20', 'YYYY-MM-DD'));
INSERT INTO cities (city_id, city_name, province, region_type, description, source_url, date_retrieved) VALUES (4, 'Gilgit', 'Gilgit-Baltistan', 'Northern Area', 'Historic Silk Road hub situated at the confluence of the Gilgit and Hunza rivers. Gateway to the Karakoram Highway, Naltar Valley, and the junction of the world''s highest mountain ranges.', 'https://visitgilgitbaltistan.gov.pk', TO_DATE('2024-11-20', 'YYYY-MM-DD'));
INSERT INTO cities (city_id, city_name, province, region_type, description, source_url, date_retrieved) VALUES (5, 'Skardu', 'Gilgit-Baltistan', 'Northern Area', 'Premier mountaineering hub of Pakistan nestled along the Indus River in the Karakoram range. Primary staging ground for expeditions to K2, Broad Peak, Gasherbrum, and the high-altitude Deosai Plains.', 'https://visitgilgitbaltistan.gov.pk', TO_DATE('2024-11-20', 'YYYY-MM-DD'));
