INSERT INTO street_foods (food_id, city_id, food_name, category, famous_spot, price_range, is_street_food, description, source_url, date_retrieved) VALUES (1, 1, 'Savour Foods Chicken Pulao Kabab', 'Traditional', 'Blue Area / G-7 Markaz', 'PKR 450 - 650', 'Y', 'Aromatic long-grain basmati rice cooked in chicken stock served with two Shami kababs and mint raita.', 'https://savourfoods.com', TO_DATE('2024-11-20', 'YYYY-MM-DD'));
INSERT INTO street_foods (food_id, city_id, food_name, category, famous_spot, price_range, is_street_food, description, source_url, date_retrieved) VALUES (2, 1, 'Peshawari Chapli Kabab', 'Barbecue', 'F-10 Markaz, Islamabad', 'PKR 500 - 800', 'Y', 'Minced beef patties infused with pomegranate seeds, coriander, crushed chili, and fresh tomato slices fried in tallow.', 'https://tourism.gov.pk', TO_DATE('2024-11-20', 'YYYY-MM-DD'));
INSERT INTO street_foods (food_id, city_id, food_name, category, famous_spot, price_range, is_street_food, description, source_url, date_retrieved) VALUES (3, 1, 'Desi Ghee Mutton Karahi', 'Savory', 'Saidpur Village / Cheema & Chattha F-11', 'PKR 2800 - 3500', 'N', 'Tender mutton slow-cooked in pure desi ghee, fresh tomatoes, green chilies, and ginger juliennes.', 'https://saidpur.cda.gov.pk', TO_DATE('2024-11-20', 'YYYY-MM-DD'));
INSERT INTO street_foods (food_id, city_id, food_name, category, famous_spot, price_range, is_street_food, description, source_url, date_retrieved) VALUES (4, 1, 'Melody Food Street Seekh Kababs', 'Barbecue', 'Melody Food Park, Sector G-6', 'PKR 350 - 550', 'Y', 'Charcoal-grilled minced beef and mutton skewers served with hot tandoori naan and spiced chutney.', 'https://cda.gov.pk', TO_DATE('2024-11-20', 'YYYY-MM-DD'));
INSERT INTO street_foods (food_id, city_id, food_name, category, famous_spot, price_range, is_street_food, description, source_url, date_retrieved) VALUES (5, 1, 'Halwa Puri Chana Platter', 'Traditional', 'Super Market F-6 / Kartarpura', 'PKR 250 - 400', 'Y', 'Crispy deep-fried puris accompanied by spicy chickpea curry, sour pickle, and rich semolina halwa.', 'https://tourism.gov.pk', TO_DATE('2024-11-20', 'YYYY-MM-DD'));
INSERT INTO street_foods (food_id, city_id, food_name, category, famous_spot, price_range, is_street_food, description, source_url, date_retrieved) VALUES (6, 1, 'Kabul Afghani Lamb Tikka', 'Barbecue', 'Super Market F-7 Markaz', 'PKR 1400 - 2200', 'N', 'Succulent chunks of salted lamb meat skewered and charcoal grilled in Afghani tradition with dumba fat.', 'https://kabulrestaurant.pk', TO_DATE('2024-11-20', 'YYYY-MM-DD'));
INSERT INTO street_foods (food_id, city_id, food_name, category, famous_spot, price_range, is_street_food, description, source_url, date_retrieved) VALUES (7, 1, 'Karachi Spicy Beef Biryani', 'Traditional', 'Sector G-9 Karachi Biryani Center', 'PKR 350 - 550', 'Y', 'Layered basmati rice with spicy marinated beef chunks, steamed potatoes, and saffron essence.', 'https://tourism.gov.pk', TO_DATE('2024-11-20', 'YYYY-MM-DD'));
INSERT INTO street_foods (food_id, city_id, food_name, category, famous_spot, price_range, is_street_food, description, source_url, date_retrieved) VALUES (8, 1, 'Monal Chicken Makhni Handi', 'Savory', 'Pir Sohawa, Margalla Hills', 'PKR 2200 - 2900', 'N', 'Creamy boneless chicken cooked in butter gravy with fenugreek and tomatoes overlooking Islamabad.', 'https://themonal.com', TO_DATE('2024-11-20', 'YYYY-MM-DD'));
INSERT INTO street_foods (food_id, city_id, food_name, category, famous_spot, price_range, is_street_food, description, source_url, date_retrieved) VALUES (9, 1, 'Hot Gulab Jamun & Rabri', 'Sweet', 'Jameel Sweets, Sector F-10 Markaz', 'PKR 150 - 300', 'Y', 'Warm cottage cheese dumplings soaked in cardamom sugar syrup topped with thick thickened rabri cream.', 'https://jameelsweets.com', TO_DATE('2024-11-20', 'YYYY-MM-DD'));
INSERT INTO street_foods (food_id, city_id, food_name, category, famous_spot, price_range, is_street_food, description, source_url, date_retrieved) VALUES (10, 1, 'Khatta Meetha Gol Gappay', 'Savory', 'F-10 Markaz Khokha', 'PKR 200 - 350', 'Y', 'Crispy semolina hollow spheres filled with spicy boiled chickpeas, potatoes, and iced tamarind mint water.', 'https://tourism.gov.pk', TO_DATE('2024-11-20', 'YYYY-MM-DD'));
INSERT INTO street_foods (food_id, city_id, food_name, category, famous_spot, price_range, is_street_food, description, source_url, date_retrieved) VALUES (11, 2, 'Waris Nihari Beef Shank', 'Traditional', 'Paisa Akhbar, Anarkali, Lahore', 'PKR 650 - 1100', 'Y', 'Slow-simmered beef shank stew cooked overnight in bone marrow gravy, garnished with ginger, lemon, and fried onions.', 'https://tdcp.gop.pk', TO_DATE('2024-11-20', 'YYYY-MM-DD'));
INSERT INTO street_foods (food_id, city_id, food_name, category, famous_spot, price_range, is_street_food, description, source_url, date_retrieved) VALUES (12, 2, 'Butt Karahi Desi Murgh', 'Savory', 'Lakshmi Chowk, Lahore', 'PKR 2400 - 3400', 'Y', 'Authentic country chicken karahi cooked in fresh butter with ginger, green chilies, and black pepper.', 'https://buttkarahi.com.pk', TO_DATE('2024-11-20', 'YYYY-MM-DD'));
INSERT INTO street_foods (food_id, city_id, food_name, category, famous_spot, price_range, is_street_food, description, source_url, date_retrieved) VALUES (13, 2, 'Gawalmandi Amritsari Hareesa', 'Traditional', 'Gawalmandi Food Street, Lahore', 'PKR 600 - 900', 'Y', 'Slow-beaten shredded meat blended with cracked wheat, aromatic spices, and desi ghee kabab garnishing.', 'https://tdcp.gop.pk', TO_DATE('2024-11-20', 'YYYY-MM-DD'));
INSERT INTO street_foods (food_id, city_id, food_name, category, famous_spot, price_range, is_street_food, description, source_url, date_retrieved) VALUES (14, 2, 'Phikke Di Jalebi', 'Sweet', 'Bohar Chowk, Inside Walled City', 'PKR 300 - 500', 'Y', 'Giant crispy orange swirls of fried batter soaked in rosewater-infused sugar syrup served warm.', 'https://wcla.punjab.gov.pk', TO_DATE('2024-11-20', 'YYYY-MM-DD'));
INSERT INTO street_foods (food_id, city_id, food_name, category, famous_spot, price_range, is_street_food, description, source_url, date_retrieved) VALUES (15, 2, 'Bashir Dar-ul-Mahi Rahu Fish', 'Savory', 'Mozang Chungi / Qaddafi Stadium', 'PKR 1800 - 2600', 'Y', 'Fresh river Rahu fish marinated in ajwain, besan, and secret spices deep-fried in hot mustard oil.', 'https://tdcp.gop.pk', TO_DATE('2024-11-20', 'YYYY-MM-DD'));
INSERT INTO street_foods (food_id, city_id, food_name, category, famous_spot, price_range, is_street_food, description, source_url, date_retrieved) VALUES (16, 2, 'Khalifa Nan Khatai', 'Sweet', 'Mochi Gate, Inside Walled City', 'PKR 600 - 1000', 'Y', 'Traditional crumbly Mughal shortbread biscuits enriched with desi ghee, cardamom, and whole almonds.', 'https://khalifanankhatai.com.pk', TO_DATE('2024-11-20', 'YYYY-MM-DD'));
