INSERT INTO reviews (review_id, hotel_id, food_id, landmark_id, reviewer_name, rating, review_text, review_date) VALUES (1, 1, NULL, NULL, 'Zubair Hashmi', 5, 'Unmatched hospitality at Islamabad Serena. The Moorish architecture and lush grounds are breathtaking.', TO_DATE('2024-10-15', 'YYYY-MM-DD'));
