INSERT INTO reviews (review_id, hotel_id, food_id, landmark_id, reviewer_name, rating, review_text, review_date) VALUES (3, 9, NULL, NULL, 'Bilal Chaudhry', 5, 'PC Lahore is iconic. Bukhara restaurant live barbeque and classical music was wonderful.', TO_DATE('2024-10-20', 'YYYY-MM-DD'));
INSERT INTO reviews (review_id, hotel_id, food_id, landmark_id, reviewer_name, rating, review_text, review_date) VALUES (4, 10, NULL, NULL, 'Sarah Khan', 5, 'Nishat Gulberg is contemporary luxury at its finest. Loved the Parisian decor and prompt service.', TO_DATE('2024-10-22', 'YYYY-MM-DD'));
