INSERT INTO reviews (review_id, hotel_id, food_id, landmark_id, reviewer_name, rating, review_text, review_date) VALUES (28, NULL, 42, NULL, 'Shehryar Munawar', 5, 'Fresh charcoal-grilled trout at Upper Kachura Lake with cold glacial breeze is unmatched.', TO_DATE('2024-11-09', 'YYYY-MM-DD'));
