INSERT INTO seasons (season_id, city_id, season_name, ideal_months, avg_temp_celsius, weather_notes, visit_rating, source_url, date_retrieved) VALUES (1, 1, 'Spring', 'March to April', '15C - 26C', 'Pleasant sunny days, Margalla Hills bloom with wildflowers. Ideal for hiking trails and outdoor gardens.', 4.9, 'https://pmd.gov.pk', TO_DATE('2024-11-20', 'YYYY-MM-DD'));
INSERT INTO seasons (season_id, city_id, season_name, ideal_months, avg_temp_celsius, weather_notes, visit_rating, source_url, date_retrieved) VALUES (2, 1, 'Summer / Monsoon', 'May to August', '26C - 39C', 'Hot afternoons with dramatic monsoon downpours in July-August. Lush greenery across the capital.', 3.8, 'https://pmd.gov.pk', TO_DATE('2024-11-20', 'YYYY-MM-DD'));
INSERT INTO seasons (season_id, city_id, season_name, ideal_months, avg_temp_celsius, weather_notes, visit_rating, source_url, date_retrieved) VALUES (3, 1, 'Autumn', 'September to November', '16C - 28C', 'Crisp golden foliage, clear mountain views, and moderate temperatures. Peak tourist trekking season.', 4.8, 'https://pmd.gov.pk', TO_DATE('2024-11-20', 'YYYY-MM-DD'));
INSERT INTO seasons (season_id, city_id, season_name, ideal_months, avg_temp_celsius, weather_notes, visit_rating, source_url, date_retrieved) VALUES (4, 1, 'Winter', 'December to February', '3C - 18C', 'Chilly dry winter with fog and occasional frost. Distant Margalla crests occasionally receive snow dusting.', 4.2, 'https://pmd.gov.pk', TO_DATE('2024-11-20', 'YYYY-MM-DD'));
INSERT INTO seasons (season_id, city_id, season_name, ideal_months, avg_temp_celsius, weather_notes, visit_rating, source_url, date_retrieved) VALUES (5, 2, 'Spring', 'February to March', '14C - 27C', 'The festive season of Jashn-e-Baharan. Mild sunny weather ideal for exploring the Walled City and gardens.', 4.9, 'https://pmd.gov.pk', TO_DATE('2024-11-20', 'YYYY-MM-DD'));
INSERT INTO seasons (season_id, city_id, season_name, ideal_months, avg_temp_celsius, weather_notes, visit_rating, source_url, date_retrieved) VALUES (6, 2, 'Summer / Monsoon', 'May to August', '28C - 42C', 'Intense heat followed by heavy monsoon rains in July. Best enjoyed indoors or during nighttime food street visits.', 3.2, 'https://pmd.gov.pk', TO_DATE('2024-11-20', 'YYYY-MM-DD'));
INSERT INTO seasons (season_id, city_id, season_name, ideal_months, avg_temp_celsius, weather_notes, visit_rating, source_url, date_retrieved) VALUES (7, 2, 'Autumn', 'October to November', '18C - 30C', 'Pleasant evenings, start of outdoor wedding festivities and cultural literary festivals.', 4.6, 'https://pmd.gov.pk', TO_DATE('2024-11-20', 'YYYY-MM-DD'));
INSERT INTO seasons (season_id, city_id, season_name, ideal_months, avg_temp_celsius, weather_notes, visit_rating, source_url, date_retrieved) VALUES (8, 2, 'Winter', 'December to January', '6C - 20C', 'Cool days with winter smog; excellent for savoring hot nihari, halwa puri, and Kashmiri chai.', 4.4, 'https://pmd.gov.pk', TO_DATE('2024-11-20', 'YYYY-MM-DD'));
INSERT INTO seasons (season_id, city_id, season_name, ideal_months, avg_temp_celsius, weather_notes, visit_rating, source_url, date_retrieved) VALUES (9, 3, 'Spring / Early Summer', 'March to April', '22C - 33C', 'Warm maritime breeze from the Arabian Sea with moderate humidity.', 4.0, 'https://pmd.gov.pk', TO_DATE('2024-11-20', 'YYYY-MM-DD'));
INSERT INTO seasons (season_id, city_id, season_name, ideal_months, avg_temp_celsius, weather_notes, visit_rating, source_url, date_retrieved) VALUES (10, 3, 'Summer / Monsoon', 'May to August', '28C - 36C', 'Humid coastal weather with sea breezes, overcast monsoon skies, and active beach waves.', 3.7, 'https://pmd.gov.pk', TO_DATE('2024-11-20', 'YYYY-MM-DD'));
INSERT INTO seasons (season_id, city_id, season_name, ideal_months, avg_temp_celsius, weather_notes, visit_rating, source_url, date_retrieved) VALUES (11, 3, 'Autumn', 'September to October', '24C - 33C', 'Post-monsoon warm days with refreshing evening sea winds across Clifton and Port Grand.', 4.2, 'https://pmd.gov.pk', TO_DATE('2024-11-20', 'YYYY-MM-DD'));
INSERT INTO seasons (season_id, city_id, season_name, ideal_months, avg_temp_celsius, weather_notes, visit_rating, source_url, date_retrieved) VALUES (12, 3, 'Winter', 'November to February', '13C - 27C', 'The golden travel season in Karachi. Perfectly mild, clear skies, ideal for water sports and heritage walks.', 5.0, 'https://pmd.gov.pk', TO_DATE('2024-11-20', 'YYYY-MM-DD'));
INSERT INTO seasons (season_id, city_id, season_name, ideal_months, avg_temp_celsius, weather_notes, visit_rating, source_url, date_retrieved) VALUES (13, 4, 'Spring', 'April to May', '10C - 22C', 'Cherry and apricot blossoms turn the valleys white and pink against rugged Karakoram cliffs.', 4.8, 'https://pmd.gov.pk', TO_DATE('2024-11-20', 'YYYY-MM-DD'));
INSERT INTO seasons (season_id, city_id, season_name, ideal_months, avg_temp_celsius, weather_notes, visit_rating, source_url, date_retrieved) VALUES (14, 4, 'Summer', 'June to August', '18C - 34C', 'Warm valley days, cool mountain nights. Prime season for high alpine trekking and KKH expeditions.', 4.9, 'https://pmd.gov.pk', TO_DATE('2024-11-20', 'YYYY-MM-DD'));
INSERT INTO seasons (season_id, city_id, season_name, ideal_months, avg_temp_celsius, weather_notes, visit_rating, source_url, date_retrieved) VALUES (15, 4, 'Autumn', 'September to October', '8C - 20C', 'Spectacular golden foliage season as poplars and apricots turn brilliant shades of gold and amber.', 5.0, 'https://pmd.gov.pk', TO_DATE('2024-11-20', 'YYYY-MM-DD'));
INSERT INTO seasons (season_id, city_id, season_name, ideal_months, avg_temp_celsius, weather_notes, visit_rating, source_url, date_retrieved) VALUES (16, 4, 'Winter', 'November to March', '-3C - 10C', 'Cold winter with snow in upper valleys; valley roads remain mostly accessible. Skiing in Naltar.', 3.5, 'https://pmd.gov.pk', TO_DATE('2024-11-20', 'YYYY-MM-DD'));
INSERT INTO seasons (season_id, city_id, season_name, ideal_months, avg_temp_celsius, weather_notes, visit_rating, source_url, date_retrieved) VALUES (17, 5, 'Spring', 'April to May', '6C - 18C', 'Apricot and almond blossom festival throughout Shigar, Khaplu, and Kachura valleys.', 4.8, 'https://pmd.gov.pk', TO_DATE('2024-11-20', 'YYYY-MM-DD'));
INSERT INTO seasons (season_id, city_id, season_name, ideal_months, avg_temp_celsius, weather_notes, visit_rating, source_url, date_retrieved) VALUES (18, 5, 'Summer', 'June to August', '14C - 28C', 'Peak mountaineering and touring season. Deosai National Park opens with carpets of wild flowers.', 5.0, 'https://pmd.gov.pk', TO_DATE('2024-11-20', 'YYYY-MM-DD'));
INSERT INTO seasons (season_id, city_id, season_name, ideal_months, avg_temp_celsius, weather_notes, visit_rating, source_url, date_retrieved) VALUES (19, 5, 'Autumn', 'September to October', '4C - 18C', 'Crystal clear skies, golden-red poplar trees reflecting in turquoise lakes, crisp mountain air.', 4.9, 'https://pmd.gov.pk', TO_DATE('2024-11-20', 'YYYY-MM-DD'));
INSERT INTO seasons (season_id, city_id, season_name, ideal_months, avg_temp_celsius, weather_notes, visit_rating, source_url, date_retrieved) VALUES (20, 5, 'Winter', 'November to March', '-12C - 4C', 'Freezing temperatures, frozen lakes, snow-covered Katpana dunes, and winter ice climbing.', 3.4, 'https://pmd.gov.pk', TO_DATE('2024-11-20', 'YYYY-MM-DD'));
